impl protocol::MutationKind<Snap, Op> for RenameNode {
    fn label(&self) -> protocol::LocalizedLabel {
        protocol::LocalizedLabel::native(&format!("Rename {} to {}", self.id, self.name), &format!("{} in {} umbenennen", self.id, self.name))
    }
}

impl MutationKind<Snap, Op> for Toggle {
    fn label(&self) -> LocalizedLabel {
        match self.on {
            true => LocalizedLabel::native("Show", "Einblenden"),
            false => LocalizedLabel::native("Hide", "Ausblenden"),
        }
    }
}

