fn delete_objects(mutations: Vec<Op>) -> Result<Emit<Op, Cfg>, Fault> {
    Ok(Emit::commit(mutations, "Delete objects"))
}

fn edit(mutation: Op, description: String) -> Result<Emit<Op, Cfg>, Fault> {
    let first = semio_framework_plugin::Emit::commit(vec![mutation.clone()], description.clone());
    let second = Emit::<Op, Cfg>::commit(vec![mutation], format!("Edit {}", description));
    Ok(first.merge(second))
}

fn fill(mutation: Op, description: Option<String>) -> Result<Emit<Op, Cfg>, Fault> {
    if mutation.is_empty() {
        return Ok(Emit { effects: start_fill_effects(), description: Some("Commit fill".into()), ..Default::default() });
    }
    Ok(semio_framework_plugin::Emit { artifact_mutations: vec![mutation], description, ..Default::default() })
}

pub struct Emit<M, C> {
    pub artifact_mutations: Vec<M>,
    pub description: Option<String>,
}
impl<M, C> Default for Emit<M, C> {
    fn default() -> Self {
        Self { artifact_mutations: Vec::new(), description: None }
    }
}
fn plain() -> Emit {
    Emit::default()
}
fn gesture(transaction: TransactionRef, ops: Vec<Op>, op: Op) -> Vec<Emit<Op, Cfg>> {
    vec![Emit::commit_transaction(transaction, ops), Emit::mutations(vec![op.clone()]), Emit { artifact_mutations: vec![op], description: None, ..Default::default() }]
}
fn publish(emit: Emit<Op, Cfg>) -> Option<String> {
    let Emit { artifact_mutations, description, .. } = emit;
    match description {
        Some(text) if artifact_mutations.is_empty() => Some(text),
        _ => None,
    }
}
